        add("research.orbitalis.node.hypergolics", "Hypergolic Propellants");
        add("research.orbitalis.node.hypergolics.desc", "Hydrazine and its relatives ignite on contact. Unlocks the hypergolic engine, loaded at the factory: no fuelling at the pad.");
        add("research.orbitalis.node.steelmaking", "Steelmaking");
        add("research.orbitalis.node.steelmaking.desc", "Steel, made in the arc foundry. Known from the start.");
        add("research.orbitalis.node.aluminum_structures", "Aluminum Structures");
        add("research.orbitalis.node.aluminum_structures.desc", "Light tanks and hulls made of aluminum plates.");
        add("research.orbitalis.node.aluminum_lithium", "Aluminum-Lithium Alloys");
        add("research.orbitalis.node.aluminum_lithium.desc", "Lighter and stiffer: every kilogram saved adds delta-v.");
        add("research.orbitalis.node.titanium_parts", "Titanium Parts");
        add("research.orbitalis.node.titanium_parts.desc", "Strong and light, for the most heavily loaded parts. Unlocks the titanium tank, the lightest.");
        add("research.orbitalis.node.superalloys", "Superalloys");
        add("research.orbitalis.node.superalloys.desc", "Inconel-type alloys that withstand combustion chamber heat. Unlocks the vacuum engine, for upper stages.");
        add("research.orbitalis.node.stainless_steel", "Stainless Steel");
        add("research.orbitalis.node.stainless_steel.desc", "Cheap and strong at both very low and very high temperatures, as on Starship. Unlocks the large stainless tank.");
        add("research.orbitalis.node.composites", "Carbon Fiber Composites");
        add("research.orbitalis.node.composites.desc", "Very light fairings and structures.");
        add("research.orbitalis.node.heat_shields", "Heat Shields");
        add("research.orbitalis.node.heat_shields.desc", "Tiles and ablative shields to survive atmospheric reentry.");
        add("research.orbitalis.node.basic_electronics", "Basic Electronics");
        add("research.orbitalis.node.basic_electronics.desc", "Simple circuits and sensors.");
        add("research.orbitalis.node.gyroscopes", "Gyroscopes");
        add("research.orbitalis.node.gyroscopes.desc", "They measure the rocket's attitude and keep it on course.");
        add("research.orbitalis.node.flight_computers", "Flight Computers");
        add("research.orbitalis.node.flight_computers.desc", "Automatic guidance, from ignition to orbit insertion.");
        add("research.orbitalis.node.telemetry", "Telemetry");
        add("research.orbitalis.node.telemetry.desc", "The rocket sends its measurements to the ground during flight: every flight that reaches space earns 3 more points.");
        add("research.orbitalis.node.solar_power", "Solar Panels");
        add("research.orbitalis.node.solar_power.desc", "Electrical power in orbit, as long as the Sun is in view. Lets you place solar panels.");
        add("research.orbitalis.node.fuel_cells", "Fuel Cells");
        add("research.orbitalis.node.fuel_cells.desc", "Electricity and water from hydrogen and oxygen, as on Gemini and Apollo. Essential for long missions: it opens orbital rendezvous.");
        add("research.orbitalis.node.rtg", "Radioisotope Generators");
        add("research.orbitalis.node.rtg.desc", "A power source for decades, far from the Sun: satellites launched afterwards last twice as long.");
        add("research.orbitalis.node.launch_pad", "Launch Pad");
        add("research.orbitalis.node.launch_pad.desc", "Launch table and flame trench for the first rockets.");
        add("research.orbitalis.node.fuel_farm", "Tank Farm");
        add("research.orbitalis.node.fuel_farm.desc", "Propellant storage and lines to the launch pad. Lets you place fuel ports.");
        add("research.orbitalis.node.service_tower", "Service Tower");
        add("research.orbitalis.node.service_tower.desc", "Umbilical arms, access to the rocket and hold-down clamps.");
        add("research.orbitalis.node.vehicle_assembly", "Vehicle Assembly Building");
        add("research.orbitalis.node.vehicle_assembly.desc", "Large launchers are assembled indoors, then rolled out to the pad. Allows three-stage launchers.");
        add("research.orbitalis.node.mission_control", "Mission Control");
        add("research.orbitalis.node.mission_control.desc", "Telemetry screens and trajectory tracking during the mission. Lets you place mission displays.");
        add("research.orbitalis.node.tracking_stations", "Tracking Stations");
        add("research.orbitalis.node.tracking_stations.desc", "Large antennas to stay in touch with distant spacecraft. Opens the tracking station's observatory and survey.");
        add("research.orbitalis.node.test_stands", "Test Stands");
        add("research.orbitalis.node.test_stands.desc", "Engine tests earn research points: each engine studied at the engineer workbench gives 15.");
        add("research.orbitalis.node.sounding_payloads", "Sounding Payloads");
        add("research.orbitalis.node.sounding_payloads.desc", "Instruments that measure the upper atmosphere during a suborbital flight.");
        add("research.orbitalis.node.first_satellite", "First Satellite");
        add("research.orbitalis.node.first_satellite.desc", "A sphere and a radio transmitter: the space age begins, as with Sputnik.");
        add("research.orbitalis.node.communication_satellites", "Communication Satellites");
        add("research.orbitalis.node.communication_satellites.desc", "Long-range communication and relays for probes.");
        add("research.orbitalis.node.navigation_satellites", "Navigation Satellites");
        add("research.orbitalis.node.navigation_satellites.desc", "A medium-orbit constellation gives your position anywhere.");
        add("research.orbitalis.node.space_telescopes", "Space Telescopes");
        add("research.orbitalis.node.space_telescopes.desc", "They discover new worlds and unlock destinations.");
        add("research.orbitalis.node.weather_satellites", "Weather Satellites");
        add("research.orbitalis.node.weather_satellites.desc", "Rain and thunderstorm forecasts.");
        add("research.orbitalis.node.earth_observation", "Earth Observation");
        add("research.orbitalis.node.earth_observation.desc", "Sun-synchronous satellites map the world.");
        add("research.orbitalis.node.life_support", "Life Support");
        add("research.orbitalis.node.life_support.desc", "Oxygen, pressure and temperature: what it takes to keep a crew alive.");
        add("research.orbitalis.node.capsules", "Crew Capsules");
        add("research.orbitalis.node.capsules.desc", "First crewed flights, like Vostok and Mercury.");
        add("research.orbitalis.node.spacesuits", "Spacesuits");
        add("research.orbitalis.node.spacesuits.desc", "Suits for launch and for spacewalks.");
        add("research.orbitalis.node.rendezvous_docking", "Rendezvous and Docking");
        add("research.orbitalis.node.rendezvous_docking.desc", "Two spacecraft meet in orbit, as in the Gemini program.");
        add("research.orbitalis.node.lunar_lander", "Lunar Lander");
        add("research.orbitalis.node.lunar_lander.desc", "Land on the Moon and take off again, like the Apollo lunar module.");
        add("research.orbitalis.node.launch_escape", "Launch Escape System");
        add("research.orbitalis.node.launch_escape.desc", "A tower pulls the capsule away from a failing rocket. Without it, the crew is hurt when their rocket breaks up.");
        add("research.orbitalis.node.station_modules", "Station Modules");
        add("research.orbitalis.node.station_modules.desc", "Habitation modules, laboratories and connecting nodes.");
        add("research.orbitalis.node.solar_arrays", "Large Solar Arrays");
        add("research.orbitalis.node.solar_arrays.desc", "Truss, Sun-tracking solar arrays and radiators.");
        add("research.orbitalis.node.closed_loop_life_support", "Closed-Loop Life Support");
        add("research.orbitalis.node.closed_loop_life_support.desc", "Air and water recycling for long stays.");
        add("research.orbitalis.node.lunar_gateway", "Lunar Orbit Station");
        add("research.orbitalis.node.lunar_gateway.desc", "An outpost around the Moon, like the Lunar Gateway. Unlocks the lunar gateway, launched like a satellite, which earns points every day from lunar orbit.");
        add("research.orbitalis.node.robotic_arm", "Robotic Arm");
        add("research.orbitalis.node.robotic_arm.desc", "It grabs cargo as it arrives, like Canadarm2: what a launcher delivers to the station is stowed in a cargo rack.");
        add("research.orbitalis.node.probes", "Robotic Probes");
        add("research.orbitalis.node.probes.desc", "They fly past other worlds and send data back. Unlocks the lunar and Mars probes, which map the body from orbit.");
        add("research.orbitalis.node.landers", "Landers");
        add("research.orbitalis.node.landers.desc", "Land softly on another celestial body. Unlocks the robotic landers, which really touch down on the Moon or Mars.");
        add("research.orbitalis.node.rovers", "Rovers");
        add("research.orbitalis.node.rovers.desc", "Exploration vehicles, like the LRV, Curiosity or Perseverance. Unlocks the rover, a solar-powered lunar buggy you set down and drive.");
        add("research.orbitalis.node.isru", "In-Situ Resources");
        add("research.orbitalis.node.isru.desc", "Make water, oxygen and fuel from local resources. Unlocks the ice drill (Moon, Mars) and the oxygen extractor (Mars).");
        add("research.orbitalis.node.planetary_bases", "Planetary Bases");
        add("research.orbitalis.node.planetary_bases.desc", "Habitats, power plants and greenhouses for a lasting presence. Unlocks the planetary base kit, which builds a pressurised module on the Moon or Mars.");
        add("research.orbitalis.node.sample_return", "Sample Return");
        add("research.orbitalis.node.sample_return.desc", "Bring rocks back to Earth for research. Unlocks robotic sample return missions and the sample container, to take samples yourself.");
        add("research.orbitalis.node.ion_propulsion", "Ion Propulsion");
        add("research.orbitalis.node.ion_propulsion.desc", "Tiny thrust but huge efficiency, using xenon. Unlocks the ion thruster, an upper stage for probes and satellites: once in orbit, it adds thousands of m/s of delta-v.");
        add("research.orbitalis.node.nuclear_thermal", "Nuclear Thermal Propulsion");
        add("research.orbitalis.node.nuclear_thermal.desc", "A reactor heats hydrogen, like NERVA. Unlocks the nuclear thermal engine, twice as efficient as a chemical engine but heavy and hungry for tanks. It's only for upper stages. Also unlocks the hydrogen tank, big and light, made for it.");
        add("research.orbitalis.node.fusion", "Fusion Propulsion");
        add("research.orbitalis.node.fusion.desc", "The power of stars, to cross the solar system. Unlocks the fusion drive, which burns helium-3 from the Moon, and the fusion reactor, which turns it into electricity.");
        add("research.orbitalis.node.warp_drive", "Warp Drive");
        add("research.orbitalis.node.warp_drive.desc", "Folding space to reach other stars. Unlocks the warp core, charged with exotic matter, which the Casimir chamber draws from the vacuum.");
        add("research.orbitalis.node.solar_sails", "Solar Sails");
        add("research.orbitalis.node.solar_sails.desc", "Sunlight pushes a huge sail, with no fuel. Unlocks the solar sail, an upper stage with no propellant, all the better as the payload is light.");

