        add("observatory.orbitalis.body.moon", "The Moon");
        add("observatory.orbitalis.body.moon.desc", "Our neighbour, three days away. Its dark basalt seas and craters keep the memory of the young solar system. A lunar module can land there.");
        add("observatory.orbitalis.body.comet", "Periodic comet");
        add("observatory.orbitalis.body.comet.desc", "A ball of ice and dust that returns every seventy years. Near the Sun it unfurls two tails: dust, curved and golden, and ions, straight and blue.");
        add("observatory.orbitalis.body.mars", "Mars");
        add("observatory.orbitalis.body.mars.desc", "The red planet: iron-oxide deserts, giant volcanoes, ice caps. Its air, a hundred times thinner than ours, barely slows a spacecraft: a Mars lander touches down on its engine.");
        add("observatory.orbitalis.body.venus", "Venus");
        add("observatory.orbitalis.body.venus.desc", "Earth's twin in size, and a hell: clouds of acid, 92 bar of pressure and 465 °C at the surface. No probe has lasted more than two hours there.");
        add("observatory.orbitalis.body.mercury", "Mercury");
        add("observatory.orbitalis.body.mercury.desc", "The closest planet to the Sun, riddled with craters. Scorching by day, frozen by night; landing there takes more energy than reaching Pluto.");
        add("observatory.orbitalis.body.jupiter", "Jupiter");
        add("observatory.orbitalis.body.jupiter.desc", "The giant of the solar system, with no surface, striped with cloud bands. Its Great Red Spot is a storm wider than Earth that has raged for centuries.");
        add("observatory.orbitalis.body.europa", "Europa");
        add("observatory.orbitalis.body.europa.desc", "A moon of Jupiter covered in ice, streaked with brown cracks. Beneath the ice lies an ocean of liquid water: one of the most promising places to look for life.");
        add("observatory.orbitalis.body.saturn", "Saturn");
        add("observatory.orbitalis.body.saturn.desc", "The ringed planet: billions of blocks of ice, from grains to houses, in a sheet only a few tens of metres thick.");
        add("observatory.orbitalis.body.titan", "Titan");
        add("observatory.orbitalis.body.titan.desc", "Saturn's great moon, under an orange haze thicker than our air. Methane rains down there, filling lakes and rivers. A parachute would almost be enough to land.");
        add("observatory.orbitalis.body.pleiades", "The Pleiades");
        add("observatory.orbitalis.body.pleiades.desc", "A cluster of young blue stars, 440 light-years away, drifting through a dust cloud: their light reflects off it as a bluish veil.");
        add("observatory.orbitalis.body.orion_nebula", "Orion Nebula");
        add("observatory.orbitalis.body.orion_nebula.desc", "A stellar nursery, 1,350 light-years away. At its heart four very young stars, the Trapezium, make all the gas glow: hydrogen in red, oxygen in teal.");
        add("observatory.orbitalis.body.eagle_nebula", "Pillars of Creation");
        add("observatory.orbitalis.body.eagle_nebula.desc", "Columns of gas and dust several light-years tall, in the Eagle Nebula. Stars are born at their tips, which the light of their neighbours slowly erodes.");
        add("observatory.orbitalis.body.crab_pulsar", "Crab Pulsar");
        add("observatory.orbitalis.body.crab_pulsar.desc", "The remains of a star that exploded in 1054, recorded by Chinese astronomers. At its centre a neutron star spins thirty times a second, sweeping space with its beams.");
        add("observatory.orbitalis.body.andromeda", "Andromeda Galaxy");
        add("observatory.orbitalis.body.andromeda.desc", "The great neighbour of our Galaxy: a trillion stars, 2.5 million light-years away. It is heading towards us, and the two galaxies will merge in four billion years.");
        add("observatory.orbitalis.body.proxima_b", "Proxima b");
        add("observatory.orbitalis.body.proxima_b.desc", "The closest planet beyond the solar system, around a red dwarf. It lies where water could stay liquid, but its star's flares batter it relentlessly.");
        add("observatory.orbitalis.body.trappist_1e", "TRAPPIST-1 e");
        add("observatory.orbitalis.body.trappist_1e.desc", "One of seven Earth-sized planets circling a small, cool star. This one could hold oceans: a world to reach one day, at the end of a very long journey.");
        add("observatory.orbitalis.body.sagittarius_a", "Sagittarius A*");
        add("observatory.orbitalis.body.sagittarius_a.desc", "The black hole at the centre of our Galaxy, four million times the mass of the Sun. Nothing escapes it, not even light; around it, infalling gas glows, its light bent into a ring.");
