        add("design.orbitalis.print.need_payload", "You need a sheet of paper, and the payload on you: %s.");
        add("design.orbitalis.print.done", "Blueprint printed: %s. Right-click with it on the table of a formed launch pad.");
        add("design.orbitalis.rocket.sounding", "Sounding Rocket");
        add("design.orbitalis.rocket.sounding.desc", "A solid motor and instruments: a hop above the atmosphere. No propellant to load.");
        add("design.orbitalis.rocket.liquid_test", "Liquid Test Rocket");
        add("design.orbitalis.rocket.liquid_test.desc", "Two pressure-fed engines and one tank: to work out fuelling.");
        add("design.orbitalis.rocket.crewed_suborbital", "Crewed Suborbital");
        add("design.orbitalis.rocket.crewed_suborbital.desc", "A capsule on a single stage: space, and back under parachutes.");
        add("design.orbitalis.rocket.orbital", "Orbital Launcher");
        add("design.orbitalis.rocket.orbital.desc", "Two kerosene stages: satellites to low or polar orbit, station module.");
        add("design.orbitalis.rocket.crewed_orbital", "Crewed Orbital");
        add("design.orbitalis.rocket.crewed_orbital.desc", "Two aluminum-lithium stages: the capsule to orbit, up to the station.");
        add("design.orbitalis.rocket.mars", "Mars Launcher");
        add("design.orbitalis.rocket.mars.desc", "The heavy launcher with larger tanks: it carries the Mars lander all the way to Mars.");
